#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-04

# =============================================================================
# Playground Visual Standard Conformance
# =============================================================================
# src/skills/shared/rules/playground-visual-standard.md §9/§10 were honor-system:
# a checklist the model was asked to self-run, with nothing verifying it did.
# Adoption was accordingly bad. Measured 2026-08-04 over the 191 artifacts that
# existed before this gate landed: --pg- tokens 39%, reduced-motion gate 29%,
# copy-prompt 24%. Those are dated observations, not a live count — the live
# count is computed below and will drift as artifacts are added.
#
# This test makes the machine-checkable subset falsifiable. It does NOT try to
# judge taste; it checks the rules that are literally greppable.
#
# Scope, deliberately split:
#   EXEMPLARS (src/skills/shared/assets/playground-exemplars/*.html) -> BLOCKING.
#       These are the templates everything else is copied from. If the gold
#       standard drifts, every artifact generated from it drifts too.
#   ARTIFACTS (docs/**/*.html) -> ADVISORY, reported by count.
#       Pre-existing files are grandfathered; blocking them today would just get
#       the test disabled. Set PLAYGROUND_STANDARD_ENFORCE=1 to gate them.
#
#       The denominator is deliberately NOT hardcoded, because there are two of
#       them and they differ: this scans the WORKING TREE, but many artifacts are
#       untracked local scratch, so CI sees fewer. Measured 2026-08-04: 192 on
#       disk, 171 tracked. Quoting one fixed number in the output would be wrong
#       on somebody's machine within a day, so the count is always computed.
#
# Checks (each maps to a numbered rule):
#   §2   --pg-* chrome tokens are defined
#   §9.7 no hex in --pg-* CHROME tokens. Hex in --series-*/--status-* DATA-MARK
#        tokens is CORRECT (they come from /dataviz validated) and is not flagged.
#   §9.1 no pure #000 / #000000 background or text
#   §6   prefers-reduced-motion gate present
#   §7   1-click copy-prompt affordance
#   §9.8 no native draggable="true" drag-and-drop
#   §9.11 no raw `<` inside a JSON island
#   §8   no physical left:/right: CSS where a logical property exists
# =============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$REPO_ROOT"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; YELLOW=$'\033[1;33m'
BLUE=$'\033[0;34m'; BOLD=$'\033[1m'; NC=$'\033[0m'

ENFORCE="${PLAYGROUND_STANDARD_ENFORCE:-0}"
EXEMPLAR_DIR="src/skills/shared/assets/playground-exemplars"

echo "=========================================="
echo "  Playground Visual Standard Conformance"
echo "=========================================="

# audit_files — reads NUL-separated paths on stdin, prints "<path>|<RULE>|<message>"
# per violation. ONE python process for the whole corpus: spawning one per file cost
# 48s over 191 artifacts, which is the kind of number that gets a gate switched off.
#
# The script is held in a variable and passed with `python3 -c`, NOT piped as a
# heredoc. `python3 - <<'PY'` reads the SCRIPT from stdin, so sys.stdin.read() then
# returns "" and every file silently audits clean: 191/191 conformant in 3.9s, green
# and completely meaningless. Keep -c.
AUDIT_PY="$(cat <<'PY'
import re, sys

def audit(path, emit):
    try:
        text = open(path, encoding="utf-8", errors="replace").read()
    except OSError as exc:
        emit("READ", str(exc))
        return

    # Strip HTML comments before rule scanning: a comment that DOCUMENTS a violation
    # ("no glow halos", "never use draggable=true") must not be reported as one.
    scan = re.sub(r"<!--.*?-->", "", text, flags=re.S)

    # §2 — chrome tokens defined
    if "--pg-" not in scan:
        emit("§2", "no --pg-* chrome tokens defined")

    # §9.7 — hex in CHROME tokens only. Data-mark tokens are hex by design.
    for m in re.finditer(r"(--pg-[a-z0-9-]+)\s*:\s*([^;{}]+)", scan):
        if re.search(r"#[0-9a-fA-F]{3,8}\b", m.group(2)):
            emit("§9.7", "hex in chrome token %s: %s" % (m.group(1), m.group(2).strip()[:40]))

    # §9.1 — no pure black
    if re.search(r"#000\b|#000000\b|\bblack\b", scan):
        emit("§9.1", "pure black (#000/#000000/black) present")

    # §6 — reduced-motion gate
    if "prefers-reduced-motion" not in scan:
        emit("§6", "no prefers-reduced-motion gate")

    # §7 — copy-prompt affordance
    if not re.search(r"clipboard|copy-prompt|Copy prompt", scan, re.I):
        emit("§7", "no copy-prompt affordance")

    # §9.8 — native HTML5 drag-and-drop is mouse-only
    if re.search(r'draggable\s*=\s*["\']true', scan):
        emit("§9.8", 'native draggable="true" (use the pointer+keyboard engine)')

    # §9.11 — two severities, because they are two different problems.
    #   `</script` inside an island terminates the element at PARSE time -> live XSS.
    #   Any other raw `<` is a robustness/style matter: it survives the tokenizer fine.
    # Conflating them produced a false alarm on three artifacts whose islands merely
    # contain "<name>", "<category>/" and "< 140".
    # tests/security/test-json-island-breakout.sh is the authority on the vector;
    # this mirrors it rather than inventing a stricter one.
    for m in re.finditer(
        r'<script[^>]*type=["\']application/json["\'][^>]*>(.*?)</script>', text, re.S
    ):
        body = m.group(1)
        if re.search(r"</script", body, re.I):
            emit("§9.11", "'</script' inside a JSON island — parse-time breakout")
            break
        if "<" in body:
            emit("§9.11-style", "raw '<' inside a JSON island (prefer \\u003c)")
            break

    # §8 — physical inset/margin/padding where a logical property exists.
    # `left: 50%` paired with translateX(-50%) is the direction-AGNOSTIC centering
    # idiom (it centers identically in LTR and RTL), so it is not a §8 violation.
    # Only genuine directional offsets are.
    phys = []
    for m in re.finditer(
        r"(?<![-\w])(?:(?:margin|padding)-(?:left|right)|left|right)\s*:\s*([^;{}]+)", scan
    ):
        value = m.group(1).strip()
        if value.startswith("50%"):
            continue
        phys.append(m.group(0).strip()[:40])
    if phys:
        emit("§8", "%d physical left/right propert%s, e.g. %s (use logical properties)"
             % (len(phys), "y" if len(phys) == 1 else "ies", phys[0]))


paths = [p.strip() for p in sys.stdin.read().split("\0") if p.strip()]
if not paths:
    # An empty work list is never expected here: both call sites check the count
    # first. Reaching this means the plumbing broke, and staying silent would print
    # "100% conformant" for a scan that never happened.
    print("(no paths on stdin)", file=sys.stderr)
    sys.exit(9)
def report(path, rule, msg):
    # Messages quote raw CSS, which can contain newlines and pipes. Either one
    # would split this record and be counted downstream as a phantom file path
    # (that is how the artifact tally drifted 21 -> 19). Flatten before printing.
    flat = " ".join(str(msg).split()).replace("|", "/")
    print("%s|%s|%s" % (path, rule, flat))


for p in paths:
    audit(p, lambda rule, msg, _p=p: report(_p, rule, msg))
PY
)"

audit_files() {
    python3 -c "$AUDIT_PY"
}

fail=0

# ---------------------------------------------------------------------------
echo
echo "${YELLOW}1. Exemplars (BLOCKING — these are the templates)${NC}"
# ---------------------------------------------------------------------------
# homeos-arieh.html is the ONE exemption, and it is documented rather than silent:
# the README pins it as "Designed by Arieh; committed verbatim — study, don't edit".
# It is the AESTHETIC bar and predates the --pg-* token system. Rewriting it to pass
# a lint would destroy the thing it exists to demonstrate. Its findings still print,
# as INFO, so the exemption never turns into an invisible hole.
VERBATIM_EXEMPT="homeos-arieh.html"

exemplar_violations=0
exemplar_count=0
shopt -s nullglob
exemplars=("$EXEMPLAR_DIR"/*.html)
exemplar_count=${#exemplars[@]}

exemplar_findings=""
if (( exemplar_count > 0 )); then
    exemplar_findings="$(printf '%s\0' "${exemplars[@]}" | audit_files)"
fi

for f in "${exemplars[@]}"; do
    name="$(basename "$f")"
    findings="$(printf '%s\n' "$exemplar_findings" | awk -F'|' -v p="$f" '$1==p {print $2 "|" $3}')"
    exempt=0
    [[ "$name" == "$VERBATIM_EXEMPT" ]] && exempt=1

    if [[ -z "$findings" ]]; then
        echo "  ${GREEN}✓${NC} $name"
    elif (( exempt == 1 )); then
        echo "  ${BLUE}i${NC} $name ${BLUE}(verbatim reference — exempt, see README)${NC}"
        while IFS='|' read -r rule msg; do
            [[ -n "$rule" ]] || continue
            echo "      ${BLUE}${rule}${NC}  ${msg}"
        done < <(printf '%s\n' "$findings")
    else
        echo "  ${RED}✗${NC} $name"
        while IFS='|' read -r rule msg; do
            [[ -n "$rule" ]] || continue
            echo "      ${RED}${rule}${NC}  ${msg}"
            exemplar_violations=$((exemplar_violations + 1))
        done < <(printf '%s\n' "$findings")
    fi
done

if (( exemplar_count == 0 )); then
    echo "  ${RED}✗ no exemplars found at ${EXEMPLAR_DIR} — the standard has nothing to copy${NC}"
    fail=1
fi
if (( exemplar_violations > 0 )); then
    fail=1
fi

# ---------------------------------------------------------------------------
echo
echo "${YELLOW}2. Shipped artifacts (ADVISORY — pre-existing files grandfathered)${NC}"
# ---------------------------------------------------------------------------
declare -A rule_counts=()
artifact_count=0
clean_count=0

if [[ -d docs ]]; then
    # grep exit 1 = no artifacts, which is fine; >1 is a real error.
    art_list=""
    art_rc=0
    art_list="$(find docs -name '*.html' -not -path 'docs/site/*' -type f)" || art_rc=$?
    if (( art_rc != 0 )); then
        echo "  ${RED}✗ find failed scanning docs/${NC}" >&2
        exit 1
    fi
    artifact_count=$(printf '%s\n' "$art_list" | sed '/^$/d' | wc -l | tr -d ' ')

    # One python process for the whole corpus, then count per (file, rule) in awk.
    # A file is "dirty" if it appears at all; a rule counts each file at most once.
    art_findings=""
    if (( artifact_count > 0 )); then
        art_findings="$(printf '%s\n' "$art_list" | sed '/^$/d' | tr '\n' '\0' | audit_files)"
    fi

    dirty_count=$(printf '%s\n' "$art_findings" | sed '/^$/d' | cut -d'|' -f1 | sort -u | wc -l | tr -d ' ')
    clean_count=$(( artifact_count - dirty_count ))

    while IFS='|' read -r rule n; do
        [[ -n "$rule" ]] || continue
        rule_counts["$rule"]="$n"
    done < <(printf '%s\n' "$art_findings" | sed '/^$/d' |
             awk -F'|' '{ key = $1 "|" $2; if (!(key in seen)) { seen[key]=1; c[$2]++ } }
                        END { for (r in c) print r "|" c[r] }')
fi

if (( artifact_count == 0 )); then
    echo "  (no artifacts under docs/)"
else
    pct=$(( clean_count * 100 / artifact_count ))
    echo "  ${clean_count}/${artifact_count} fully conformant (${pct}%)"
    echo ""
    echo "  files failing each rule:"
    for rule in "§2" "§6" "§7" "§8" "§9.1" "§9.7" "§9.8" "§9.11" "§9.11-style"; do
        n="${rule_counts[$rule]:-0}"
        if (( n > 0 )); then
            echo "    ${YELLOW}${rule}${NC}  ${n}"
        fi
    done
fi

# §9.11 proper is a security invariant, never advisory — it is an XSS vector, not a
# style rule. §9.11-style (a non-breakout `<`) stays advisory: it is harmless to the
# tokenizer, and treating the two alike produces false alarms that get gates disabled.
if (( ${rule_counts["§9.11"]:-0} > 0 )); then
    echo ""
    echo "  ${RED}✗ §9.11 '</script' in a JSON island is a parse-time XSS vector.${NC}"
    echo "    See tests/security/test-json-island-breakout.sh"
    fail=1
fi

echo ""
if (( artifact_count > 0 && clean_count < artifact_count )); then
    echo "${YELLOW}Artifacts are advisory. Set ${BOLD}PLAYGROUND_STANDARD_ENFORCE=1${NC}${YELLOW} to gate on them.${NC}"
    if [[ "$ENFORCE" == "1" ]]; then fail=1; fi
fi

if (( fail == 0 )); then
    echo "${GREEN}✓ Exemplars conform to the playground visual standard${NC}"
else
    echo "${RED}✗ Playground standard conformance failed${NC}"
fi

exit "$fail"
